export type ReportFile = { name: string; mtimeMs: number; text: string }

/** The contents of `delivered.json`: a number per agent and `_decision`, and `_line:<name>` holds the last REPORT line sent. */
export type Marks = Record<string, number | string>

const LINE_KEY = '_line:'

export function reportLine(text: string): string | null {
  for (const line of text.split('\n')) {
    if (line.trim().startsWith('REPORT ')) return line.trim()
  }
  return null
}

/** A numeric mark; a missing key or a text mark counts as 0. */
export function numberMark(marks: Marks | null, key: string): number {
  const mark = marks?.[key]
  return typeof mark === 'number' ? mark : 0
}

/** The marks to write: what is on disk now, with each incoming mark on top. A number never goes down. */
export function mergeMarks(disk: Marks | null, incoming: Marks): Marks {
  const merged: Marks = { ...(disk ?? {}) }
  for (const [key, mark] of Object.entries(incoming)) {
    const now = merged[key]
    merged[key] = typeof mark === 'number' && typeof now === 'number' ? Math.max(now, mark) : mark
  }
  return merged
}

/**
 * New REPORT lines since the marks; no marks yet means a baseline that sends nothing.
 * A file newer than its mark whose line equals the last line sent for that agent is marked, not sent.
 */
export function pickReports(
  files: ReportFile[],
  delivered: Marks | null,
): { lines: string[]; delivered: Marks } {
  const marks: Marks = { ...(delivered ?? {}) }
  const lines: string[] = []
  for (const f of files) {
    if (delivered !== null && f.mtimeMs > numberMark(delivered, f.name)) {
      const line = reportLine(f.text)
      if (line && line !== delivered[LINE_KEY + f.name]) {
        lines.push(line)
        marks[LINE_KEY + f.name] = line
      }
    }
    marks[f.name] = Math.max(numberMark(marks, f.name), f.mtimeMs)
  }
  return { lines, delivered: marks }
}

files.hooks/mod/reset.ts:
import { activeConfig } from './activation'
import type { Io, ToolResult } from './io'
import { runDir } from './paths'

/** The nudge goes out at this share of the auto-compact threshold (a token count), when auto-compact is on. */
export const AUTOCOMPACT_SHARE = 0.7
/** The nudge goes out at this share of the context window when no auto-compact threshold exists. */
export const WINDOW_SHARE = 0.6
/** A handover file older than the request by more than this is stale: the orchestrator must write it again. */
export const HANDOVER_MAX_AGE_MS = 10 * 60 * 1000

export const HANDOVER_FILE = 'orch-handover.md'
export const RESET_TOOL = 'reset_self'
export const RESET_TOOL_SPEC = {
  name: RESET_TOOL,
  description:
    'Ask the team mod to compact your context at the next idle moment. Call it only at a safe point, ' +
    `after you wrote scratchpad/current/${HANDOVER_FILE}. It refuses when that file is missing or stale.`,
  inputSchema: { type: 'object', properties: {} },
}

/**
 * Where the open cards are, in words the orchestrator can act on. The `queue` tool refuses in the orchestrator
 * session, so the text names the files. `ask` writes `<run dir>/.team/questions/Q-<n>.json` (hooks/mod/questions.ts)
 * and `status` is `open`, or `assumed` for a parked card (`queueGroups` in hooks/mod/cards.ts lists both).
 */
const OPEN_CARDS =
  'the open cards (the files scratchpad/current/.team/questions/Q-*.json whose status is open or assumed)'

/**
 * What the summary of an orchestrator compact must keep, and what the orchestrator reads afterwards.
 * `hooks/handlers/session-start.sh` carries the same text for the SessionStart pointer: change both.
 */
export const COMPACT_INSTRUCTIONS =
  'You are the team orchestrator. Keep the ticket of this run, the agents in flight (name, pane, session, topic, brief) ' +
  'and the open cards. After the compact: reload the team-orchestration skill, read the decisions file, then ' +
  `scratchpad/current/${HANDOVER_FILE}, the plan file and scratchpad/current/orchestration-decisions.md, then the reports ` +
  `newer than ${HANDOVER_FILE}, then ${OPEN_CARDS}.`

/**
 * The line the mod sends after its own compact resolved. No turn starts after an idle-time compact, so this
 * line starts one: the orchestrator reloads at once instead of at some later line.
 */
export const RESUME_LINE =
  'RESUME after compact: reload the team-orchestration skill, read the decisions file, ' +
  `scratchpad/current/${HANDOVER_FILE}, the plan file, scratchpad/current/orchestration-decisions.md, ` +
  `the reports newer than the handover and ${OPEN_CARDS}, then continue from the handover`

/** The WATCH line the mod sends once per crossing of the nudge limit. */
export const nudgeLine = (percent: number) =>
  `WATCH context ${percent} percent: reach a safe point, write scratchpad/current/${HANDOVER_FILE}, then call ${RESET_TOOL}`

/** The context figures of `$.session.usage({ breakdown })` that the nudge reads. */
export type ContextFigures = {
  /** Input tokens of the last response; absent until the first response of the live window. */
  tokens?: number
  /** The model's context window (`context.window`). */
  window: number
  /**
   * The window `/context` and the auto-compact measure against (`breakdown.rawMaxTokens`): the model's limit or a
   * smaller compaction window. Absent without a breakdown.
   */
  compactWindow?: number
  /** The token count at which auto-compact runs; absent when it is off. */
  autoCompactThreshold?: number
}

/** The two engine calls the reset needs. The mod test mock answers neither, so the logic reaches them through this port. */
export type ResetPort = {
  figures: () => Promise<ContextFigures>
  /** Resolves `{}` when the conversation was compacted, `{ skip }` when a hook vetoed it; rejects while a turn runs. */
  compact: (instructions: string) => Promise<{ skip?: string }>
}

/** The token count at which the nudge goes out. */
export function nudgeLimit(f: ContextFigures): number {
  if (f.autoCompactThreshold !== undefined && f.autoCompactThreshold > 0) return f.autoCompactThreshold * AUTOCOMPACT_SHARE
  return f.window * WINDOW_SHARE
}

/**
 * The context fill in percent, null while no response has measured it. The figure is `tokens` over the compact
 * window, which is the window `/context` shows. The model window is the fallback when no breakdown gave one:
 * `context.percent` is not used, it is measured against the model window and read 23 where `/context` read 67.
 */
export function contextPercent(f: ContextFigures): number | null {
  const window = f.compactWindow !== undefined && f.compactWindow > 0 ? f.compactWindow : f.window
  if (f.tokens === undefined || window <= 0) return null
  return Math.round((f.tokens / window) * 100)
}

/**
 * One nudge decision. `armed` is true until a nudge went out; it becomes true again when the context falls
 * below the limit, or when a compact lands (`onCompacted`). An unmeasured context changes nothing.
 */
export function nudgeStep(armed: boolean, f: ContextFigures): { send: boolean; armed: boolean } {
  if (f.tokens === undefined) return { send: false, armed }
  if (f.tokens >= nudgeLimit(f)) return { send: armed, armed: false }
  return { send: false, armed: true }
}

export type Gate = {
  pending: boolean
  turnRunning: boolean
  retryLines: number
  sendsInFlight: number
  compacting: boolean
}

/** True when a requested compact may run now: no turn, no unsent line, no send in flight, no compact under way. */
export const canCompact = (g: Gate): boolean =>
  g.pending && !g.turnRunning && g.retryLines === 0 && g.sendsInFlight === 0 && !g.compacting

/** The instructions of a compact with the handover text added after any already present. */
export function withHandoverInstructions(existing?: string): string {
  const own = existing?.trim() ?? ''
  if (own === '') return COMPACT_INSTRUCTIONS
  if (own.includes(COMPACT_INSTRUCTIONS)) return own
  return `${own}\n\n${COMPACT_INSTRUCTIONS}`
}

/** Why a handover file does not count, or null when it does. `mtime` is null for a missing file. */
export function handoverVerdict(mtime: number | null, now: number): string | null {
  if (mtime === null) return `${HANDOVER_FILE} does not exist: write it, then call ${RESET_TOOL} again`
  if (mtime < now - HANDOVER_MAX_AGE_MS) {
    return `${HANDOVER_FILE} is older than 10 minutes: write it again, then call ${RESET_TOOL}`
  }
  return null
}

// Module memory only: a mod restart loses it. A new session.start resets it; a /clear keeps it.
let armed = true
let requestedAt: number | null = null
let turnRunning = false
let compacting = false

export const requestReset = (at: number) => {
  requestedAt = at
}
export const noteMainTurn = (running: boolean) => {
  turnRunning = running
}
/** A compact landed, whoever ran it: the request is met and the nudge may go out again. */
export const onCompacted = () => {
  requestedAt = null
  armed = true
}
export const clearResetState = () => {
  armed = true
  requestedAt = null
  turnRunning = false
  compacting = false
}

/** The nudge line to send now, or none. Reads the context through the port; a failed read sends nothing. */
export async function nudgeLines(port: ResetPort): Promise<string[]> {
  if (requestedAt !== null) return []
  let figures: ContextFigures
  try {
    figures = await port.figures()
  } catch {
    return []
  }
  const step = nudgeStep(armed, figures)
  armed = step.armed
  return step.send ? [nudgeLine(contextPercent(figures) ?? 0)] : []
}

/**
 * Starts the requested compact when the session is idle. Returns false when the gate was closed and nothing
 * ran, true once a call was made (and has settled). A rejected or skipped call keeps the request and tells
 * `report` why, so the next tick tries again. A resolved call calls `resume` once, after the compact flag is
 * down: it must start the turn that does the reload (no turn follows an idle-time compact by itself).
 * `resume` does not wait for the send, so a long submit never holds the next compact back.
 */
export async function compactWhenIdle(
  port: ResetPort, busy: { retryLines: number; sendsInFlight: number }, report: (text: string) => Promise<void>,
  resume: () => void,
): Promise<boolean> {
  if (!canCompact({ pending: requestedAt !== null, turnRunning, compacting, ...busy })) return false
  compacting = true
  let resolved = false
  try {
    const done = await port.compact(COMPACT_INSTRUCTIONS)
    if (done.skip !== undefined) await report(`compact skipped: ${done.skip.slice(0, 160)}`)
    else {
      onCompacted()
      resolved = true
    }
  } catch (err) {
    await report(`compact refused: ${String(err).slice(0, 160)}`)
  } finally {
    compacting = false
  }
  if (resolved) resume()
  return true
}

/** The `reset_self` tool: records the request. A tool call runs in a turn, and a compact cannot, so the tick compacts. */
export async function resetSelf(io: Io): Promise<ToolResult> {
  if (!(await activeConfig(io))) return { result: `${RESET_TOOL} works only in the orchestrator session`, isError: true }
  const now = await io.now()
  const refusal = handoverVerdict(await io.mtime(`${await runDir(io)}/${HANDOVER_FILE}`), now)
  if (refusal !== null) return { result: refusal, isError: true }
  requestReset(now)
  return { result: 'compact requested: the mod compacts at the next idle moment; stop your turn now' }
}

files.hooks/mod/tick.ts:
import type { TeamAgentRow, TeamCard } from '../../types'
import type { StallWorker } from './badge'
import type { DecisionEntry } from './decide'
import { gatherFacts, reportIsFresh } from './facts'
import type { AgentFacts } from './facts'
import { bySession, herdrClose, herdrDialog, herdrPanes } from './herdr'
import type { HerdrAgent, HerdrListing, HerdrPane } from './herdr'
import { idleTabs, layoutActions } from './layout'
import type { LayoutInput } from './layout'
import { releasedLine, releaseAgent, releaseDue, releaseFailedLine } from './release'
import { watchLines } from './watch'
import type { WatchMemory } from './watch'
import { readJson, writeJson } from './io'
import type { Io } from './io'
import { mergeMarks, pickReports } from './reports'
import type { Marks, ReportFile } from './reports'

export type TeamRecord = {
  role: string
  topic: string
  brief: string
  pane: string
  session?: string
  cwd?: string
  brief_sent_session?: string
  /** The session `brief_send` last briefed. Unlike `brief_sent_session`, a /compact keeps it; a /clear moves `session` past it. */
  watch_session?: string
}

const NON_RECORD = new Set([
  'config.json', 'watch-state.json', 'tabs.json', 'layout-flags.json', 'delivered.json', 'toasted.json',
  'next-action.json',
])

export async function readRecords(io: Io, teamdir: string): Promise<Record<string, TeamRecord>> {
  const out: Record<string, TeamRecord> = {}
  for (const file of (await io.list(teamdir)).sort()) {
    if (!file.endsWith('.json') || NON_RECORD.has(file)) continue
    const rec = await readJson<TeamRecord>(io, `${teamdir}/${file}`)
    if (rec) out[file.slice(0, -'.json'.length)] = rec
  }
  return out
}

export async function reportFiles(io: Io, run: string, records: Record<string, TeamRecord>): Promise<ReportFile[]> {
  const files: ReportFile[] = []
  for (const [name, rec] of Object.entries(records)) {
    if (rec.role === 'orchestrator') continue
    const path = `${run}/reports/${name}-${rec.topic}.md`
    const at = await io.mtime(path)
    const text = at === null ? null : await io.readText(path)
    if (at !== null && text !== null) files.push({ name, mtimeMs: at, text })
  }
  return files
}

/**
 * REPORT lines new since the last tick. `delivered` holds the marks as read.
 * `commit` writes them BEFORE the lines are sent, with `extra` marks merged in, and never lowers a mark
 * on disk. Nothing writes a mark back down: a send that fails is retried from memory (see `sendLines`).
 */
export async function newReportLines(io: Io, run: string, teamdir: string,
                                     records: Record<string, TeamRecord>,
): Promise<{
  lines: string[]
  delivered: Marks
  /** True when the file exists but cannot be used: the tick sends no REPORT or DECISION line and writes no mark. */
  unreadable: boolean
  path: string
  commit: (extra?: Marks) => Promise<void>
}> {
  const path = `${teamdir}/delivered.json`
  const read = await readMarks(io, path)
  const picked = pickReports(await reportFiles(io, run, records), read.marks)
  return {
    lines: picked.lines,
    delivered: picked.delivered,
    unreadable: read.unreadable,
    path,
    commit: async (extra = {}) => {
      const disk = await readMarks(io, path)
      if (disk.unreadable) throw new Error('delivered.json does not parse')
      await writeJson(io, path, mergeMarks(disk.marks, { ...picked.delivered, ...extra }))
    },
  }
}

/**
 * The marks on disk. A missing file is a first run (`marks` null). A file that exists but cannot be read, does
 * not parse, is empty or is not an object, is `unreadable`: reading it as missing would make the next tick send every old decision.
 */
async function readMarks(io: Io, path: string): Promise<{ marks: Marks | null; unreadable: boolean }> {
  const text = await io.readText(path)
  // `readText` turns every read error into null. A file the stat still finds exists but cannot be read.
  if (text === null) return { marks: null, unreadable: (await io.mtime(path)) !== null }
  try {
    const parsed: unknown = JSON.parse(text)
    if (typeof parsed === 'object' && parsed !== null && !Array.isArray(parsed)) return { marks: parsed as Marks, unreadable: false }
  } catch {
    // falls through to unreadable
  }
  return { marks: null, unreadable: true }
}

/** The ledger `decide` writes: one entry per decision under `<teamdir>/decisions/`. */
export async function readLedger(io: Io, teamdir: string): Promise<DecisionEntry[]> {
  const entries: DecisionEntry[] = []
  for (const name of await io.list(`${teamdir}/decisions`)) {
    if (!/^\d+\.json$/.test(name)) continue
    const entry = await readJson<DecisionEntry>(io, `${teamdir}/decisions/${name}`)
    if (entry) entries.push(entry)
  }
  return entries
}

const NO_REPORT_AFTER = 120

/** The suffix of a blocked WATCH line: the one fact the orchestrator gives `ask` for a card about the prompt. */
const promptOfHint = (name: string) => `a card about this prompt sets prompt_of: ${name}`

const CLOSED_PREFIX = 'Closed by the team mod: '

/**
 * The WATCH line that tells the orchestrator the team mod closed its card: the card id, the agent the card
 * was about, and the reason the mod wrote on the card (prefix and final full stop cut). When the card closed
 * because a different prompt shows in the same pane, the line also carries that prompt's dialog and the
 * `prompt_of` hint: the worker never left `blocked`, so no blocked line follows, and this is the orchestrator's
 * only chance to file a card for the new prompt.
 */
const closedCardLine = (card: TeamCard) => {
  const reason = (card.reason ?? '').replace(CLOSED_PREFIX, '').replace(/\.$/, '')
  const agent = card.prompt ? ` (${card.prompt.agent})` : ''
  const next = card.next_dialog && card.prompt
    ? `; it is now blocked on a new prompt: ${card.next_dialog} - ${promptOfHint(card.prompt.agent)}`
    : ''
  return `WATCH ${card.id} closed${agent}: ${reason}${next}`
}

/** The input of the layout rules from the records and herdr's two listings; `myId` is this session's id. */
async function layoutInput(
  io: Io, teamdir: string, records: Record<string, TeamRecord>, agents: HerdrAgent[], panes: HerdrPane[],
  briefed: Map<string, boolean>, myId: string, exemptTabs: string[],
): Promise<LayoutInput> {
  const marked = new Set(await io.list(`${teamdir}/pending`))
  const pendingFile = (pane: string) => pane.replace(/[:/]/g, '_')
  return {
    panes,
    teamTabs: (await readJson<string[]>(io, `${teamdir}/tabs.json`)) ?? [],
    orchTabs: [agents.find(a => a.agent_session?.value === myId)?.tab_id, ...exemptTabs]
      .filter((t): t is string => !!t),
    namedPanes: new Set(Object.values(records).map(r => r.pane)),
    pending: new Set(panes.map(p => p.pane_id).filter(id => marked.has(pendingFile(id)))),
    briefed,
    prevFlags: (await readJson<string[]>(io, `${teamdir}/layout-flags.json`)) ?? [],
  }
}

/**
 * WATCH lines for this tick: blocked turns (with their dialog), missing
 * reports, layout flags, and herdr going down. Closes empty panes a record
 * names. Releases an agent that stayed idle with a fresh report for
 * RELEASE_AFTER_MIN, and adds one line for it. Remembers what it flagged in
 * watch-state.json and layout-flags.json. `openCards` names the agents with
 * a card still open. `delivery` says whether delivered.json is broken: one line
 * when that starts and one when it ends (the latch is `delivered_broken` in
 * watch-state.json). Everything else runs the same while it is broken.
 */
export async function watchTick(
  io: Io, run: string, teamdir: string, records: Record<string, TeamRecord>,
  listed: HerdrListing, now: number, myId: string, exemptTabs: string[], openCards: Set<string>,
  delivery: { broken: boolean; path: string }, modClosed: TeamCard[] = [],
): Promise<string[]> {
  const memPath = `${teamdir}/watch-state.json`
  const mem = (await readJson<WatchMemory>(io, memPath)) ?? { agents: {}, _flagged: {}, _idle_since: {} }
  const wasBroken = mem.delivered_broken === true
  const recovered = wasBroken && !delivery.broken
  const out: string[] = []
  // A card the team mod closed gets one line, whether herdr is up or not. The mark lists every card told so far.
  const told = mem._closed_told ?? []
  out.push(...modClosed.filter(c => !told.includes(c.id)).map(closedCardLine))
  mem._closed_told = modClosed.map(c => c.id)
  if (delivery.broken && !wasBroken) {
    out.push(`WATCH delivered.json does not parse: ${delivery.path} - REPORT and DECISION delivery held until it is fixed`)
  }
  if (recovered) out.push('WATCH delivered.json parses again: REPORT and DECISION delivery resumed')
  if (!listed.ok) {
    // A timer must not run across a gap in what herdr shows: the agent may have worked in it.
    await writeJson(io, memPath, {
      ...mem, _release_since: {}, _release_tried: {}, herdr_down: true, delivered_broken: delivery.broken,
    })
    if (!mem.herdr_down) out.push(`WATCH herdr unreachable: ${listed.reason}`)
    return out
  }

  const sessions = bySession(listed.agents)
  const facts: AgentFacts[] = []
  for (const [name, rec] of Object.entries(records)) {
    if (rec.role === 'orchestrator') continue
    const agent = rec.session ? sessions.get(rec.session) : undefined
    if (agent) facts.push(await gatherFacts(io, run, name, rec, agent.agent_status, now, NO_REPORT_AFTER))
  }
  // After an outage of delivered.json the timers are stale, as after herdr was down: they start again.
  const base: WatchMemory = { ...mem, herdr_down: false }
  if (recovered) Object.assign(base, { _release_since: {}, _release_tried: {} })
  const result = watchLines(facts, base, now, NO_REPORT_AFTER)
  result.mem.delivered_broken = delivery.broken
  result.mem._closed_told = mem._closed_told
  const panes = await herdrPanes(io)
  const layout = panes
    ? await layoutInput(io, teamdir, records, listed.agents,
        panes, new Map(facts.filter(f => records[f.name]?.brief).map(f => [f.pane, f.hasFreshReport])), myId, exemptTabs)
    : null
  // Never the agent of this session. A release not yet tried is marked tried before its steps run, so an
  // overlapping tick, or a step that fails, cannot start it a second time.
  const due = layout && panes
    ? releaseDue({
        facts: facts.filter(f => records[f.name]?.session !== myId),
        since: result.mem._release_since ?? {},
        tried: result.mem._release_tried ?? {},
        paneTab: new Map(panes.map(p => [p.pane_id, p.tab_id])),
        teamTabs: layout.teamTabs,
        orchTabs: layout.orchTabs,
        openCards,
        now,
      })
    : []
  for (const name of due) result.mem._release_tried![name] = true
  await writeJson(io, memPath, result.mem)
  for (const line of result.lines) {
    const name = line.slice('WATCH '.length).split(':')[0] ?? ''
    const pane = records[name]?.pane
    if (!result.blocked.includes(name)) {
      out.push(line)
      continue
    }
    const dialog = pane ? await herdrDialog(io, pane) : ''
    out.push(`${line}${dialog ? `: ${dialog}` : ''} - ${promptOfHint(name)}`)
  }

  if (layout) {
    const actions = layoutActions(layout)
    for (const pane of actions.closes) await herdrClose(io, pane)
    await writeJson(io, `${teamdir}/layout-flags.json`, actions.flags)
    out.push(...actions.fresh.map(f => `WATCH ${f}`))
  }
  for (const name of due) {
    const pane = facts.find(f => f.name === name)?.pane ?? ''
    const released = await releaseAgent(io, name)
    out.push(released.ok ? releasedLine(name, pane) : releaseFailedLine(name, released.step, released.reason))
  }
  return out
}

/**
 * The rows of idle team tabs for the Team overview, with the pane statuses seen. Read-only: the envoy session
 * draws them. The orchestrator's mod releases an agent after RELEASE_AFTER_MIN only in a team tab (tabs.json),
 * the same tabs as these rows, and not in an exempt tab; this list adds the rule that every briefed agent in
 * the tab has reported. `briefed` is the map the rule reads, pane id to "has a fresh report", for every
 * briefed agent herdr lists; the stall flag reads it too, so the reports are read once.
 */
export async function idleTabRows(
  io: Io, run: string, teamdir: string, records: Record<string, TeamRecord>,
  listed: HerdrListing, myId: string, exemptTabs: string[],
): Promise<{ rows: string[]; briefed: Map<string, boolean> }> {
  const briefed = new Map<string, boolean>()
  if (!listed.ok) return { rows: [], briefed }
  const panes = await herdrPanes(io)
  const sessions = bySession(listed.agents)
  for (const [name, rec] of Object.entries(records)) {
    if (rec.role === 'orchestrator' || !rec.brief) continue
    const agent = rec.session ? sessions.get(rec.session) : undefined
    if (agent) briefed.set(agent.pane_id, await reportIsFresh(io, run, name, rec))
  }
  if (!panes) return { rows: [], briefed }
  return { rows: idleTabs(await layoutInput(io, teamdir, records, listed.agents, panes, briefed, myId, exemptTabs)), briefed }
}

/**
 * What the stall flag needs about each worker: its herdr state and whether its report is fresh. The
 * orchestrator's record and this session's own record are no workers. A worker without a brief owes no
 * report, so it counts as fresh.
 */
export function stallWorkers(
  records: Record<string, TeamRecord>, rows: TeamAgentRow[], briefed: Map<string, boolean>, myId: string,
): StallWorker[] {
  return rows
    .filter(r => records[r.name] && records[r.name]!.role !== 'orchestrator' && records[r.name]!.session !== myId)
    .map(r => ({ state: r.state, fresh: briefed.get(r.pane) ?? true }))
}

/** A pane id herdr moved is written back to the record, and into `records` for the rest of the tick. */
export async function syncPanes(
  io: Io, teamdir: string, records: Record<string, TeamRecord>, listed: HerdrListing,
): Promise<void> {
  if (!listed.ok) return
  const sessions = bySession(listed.agents)
  for (const [name, rec] of Object.entries(records)) {
    const agent = rec.session ? sessions.get(rec.session) : undefined
    if (!agent || agent.pane_id === rec.pane) continue
    rec.pane = agent.pane_id
    const path = `${teamdir}/${name}.json`
    const latest = await readJson<TeamRecord>(io, path)
    if (latest) await writeJson(io, path, { ...latest, pane: agent.pane_id })
  }
}

/** One row per record, read-only: the pane shown is the one herdr reports. */
export function agentRows(records: Record<string, TeamRecord>, listed: HerdrListing): TeamAgentRow[] {
  const sessions = listed.ok ? bySession(listed.agents) : new Map<string, HerdrAgent>()
  return Object.entries(records).map(([name, rec]) => {
    const agent = rec.session ? sessions.get(rec.session) : undefined
    return { name, state: agent ? agent.agent_status : listed.ok ? 'gone' : '?', pane: agent ? agent.pane_id : rec.pane }
  })
}

